create table users (id uuid primary key, email varchar(320) not null unique, display_name varchar(255), tone varchar(32) not null default 'PROFESSIONAL', timezone varchar(64) not null default 'UTC', created_at timestamp with time zone not null);
create table emails (id uuid primary key, user_id uuid not null references users(id), provider_id varchar(255) not null, thread_id varchar(255), sender varchar(500) not null, recipients text, subject varchar(998), body text not null, received_at timestamp with time zone not null, priority varchar(16) not null, status varchar(16) not null, summary text, embedding text, unique(user_id, provider_id));
create table tasks (id uuid primary key, user_id uuid not null references users(id), email_id uuid references emails(id), title varchar(500) not null, due_at timestamp with time zone, completed boolean not null default false, created_at timestamp with time zone not null);
create table calendar_events (id uuid primary key, user_id uuid not null references users(id), email_id uuid references emails(id), title varchar(500) not null, starts_at timestamp with time zone not null, ends_at timestamp with time zone, location varchar(500), external_id varchar(255));
